import { Bubble, BubbleContent } from "@/registry/erbium/ui/bubble";
import { Message, MessageContent } from "@/registry/erbium/ui/message";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof Message>) => (
  <Message {...args} className={`w-80 ${args.className ?? ""}`}>
    <MessageContent>
      <Bubble>
        <BubbleContent>Message content</BubbleContent>
      </Bubble>
    </MessageContent>
  </Message>
);

export default Example;
